def num(x, nd=1, lang='en'):
    s = f'{x:,.{nd}f}'
    if lang == 'fr': s = s.replace(',', ' ').replace('.', ',').replace(' ', NNBSP)
    return s.replace('-', '−')


def pc(x, nd=1, lang='en'): return num(100 * x, nd, lang) + (NNBSP + '%' if lang == 'fr' else '%')


class Cite:
    def __init__(self): self.order = []
    def __call__(self, *keys):
        out = []
        for k in keys:
            assert k in REFS, k
            if k not in self.order: self.order.append(k)
            out.append(self.order.index(k) + 1)
        out = sorted(out); parts = []; i = 0
        while i < len(out):
            j = i
            while j + 1 < len(out) and out[j + 1] == out[j] + 1: j += 1
            parts.append(f'{out[i]}–{out[j]}' if j - i >= 2 else ','.join(map(str, out[i:j + 1])))
            i = j + 1
        return '[' + ','.join(parts) + ']'


def rng(vals, lang, nd=1): return f"{num(min(vals), nd, lang)}–{num(max(vals), nd, lang)}"


def prng(vals, lang, nd=1): return f"{num(100 * min(vals), nd, lang)}–{num(100 * max(vals), nd, lang)}" + (NNBSP + '%' if lang == 'fr' else '%')


