    Bk = []
    add = lambda kind, en, fr=None: Bk.append(dict(kind=kind, text=en if lang == 'en' or fr is None else fr))
    sites = [ST[k] for k in ('DKQ', 'LEH', 'BRE', 'STN', 'LRO', 'FOS')]
    inc = [r['cascade_increment_MEUR'] for r in sites]; flc = [r['first_law'] for r in sites]; flh = [r['first_law_hp_only'] for r in sites]
    beP = [r['alginate_pack_breakeven_eur_kg'] for r in sites if r['alginate_t'] > 0]; beC = [r['alginate_food_plus_pack_breakeven_eur_kg'] for r in sites if r['alginate_t'] > 0]
    md = TH['med_design']; cops = TH['cop']; bb = BRIDGE['Brest']; SN_ = {r['key']: r['site'] for r in R['site_table']}
    wbe = list(WBE.values())
    add('articletype', 'Original Article', 'Article original')
