    add('subtitle', T('Version 17 → Version 18: response to the informal referee report on V17 (12 November 2026).', 'Version 17 → version 18 : réponse au rapport informel sur la V17 (12 novembre 2026).'))
    for h, t in [
        (T('Kelp-hub deployment', 'Déploiement des pôles d’algues'), T(f"Agreed. Built capacity is now separated from fuel dispatched: built hubs run on variable cost and always pay their fixed cost, and the build size is chosen by total 2027–2041 cost over 0–36 hubs (Supplementary Table S16). Central costs: 6 pilot hubs; a programme sized to the 2041 steady-state fuel balance (about 24 hubs) costs €0.11 bn more for the same mandated volumes. With all cost levers: 36 hubs. The {num(EB['hubs_for_hybrid_fuel'], 0)}-hub figure of the motorway screening is now labelled as a kelp-only upper bound.", f"D’accord. Capacité construite et carburant appelé sont séparés ; le nombre de pôles est choisi sur le coût total : 6 pôles pilotes aux coûts centraux, 36 avec tous les leviers.")),
        (T('RFNBO eligibility', 'Éligibilité RFNBO'), T(f"Agreed. E-fuel is split into RFNBO (renewable PPA with hourly matching per Delegated Regulation 2023/1184, modelled on ERA5 offshore-wind output at each coast, with utilisation-dependent plant cost and a hydrogen buffer; imports as backstop) and low-carbon e-fuel (nuclear/grid baseload; counts for the SAF share, FuelEU and road). Only RFNBO counts for the synthetic sub-mandate centrally; a sensitivity follows the reading that low-carbon synthetic fuel also counts. Synthetic premium €1.51/L (€0.00 in the sensitivity); marginal SAF €3.32/L.", f"D’accord. E-carburant RFNBO (appariement horaire) et bas-carbone (nucléaire) distingués ; surcoût synthétique 1,51 €/L.")),
        (T('Electricity boundary', 'Périmètre électrique'), T(f"Agreed. Section 3.9 and new Table S15 report the 2041 electricity by use (149 TWh) and the offshore-wind and electrolyser capacity behind it, and state that generation, transmission and connections are not built or financed in the model: a screening scenario, not an investment plan.", "D’accord. Section 3.9 et tableau S15 : électricité par usage et capacités ; scénario de criblage, non plan d’investissement.")),
        (T('Anchoring and wind contracts', 'Ancrages et contrats éoliens'), T('Agreed. The abstract now says the anchor sharing is assumed, and the limitations state that anchoring and wind contracts are assumptions needing commercial agreements and site-specific engineering.', 'D’accord. Résumé et limites précisent le caractère supposé des ancrages et des contrats.')),
        (T('Scope', 'Périmètre'), T('Agreed in part. The abstract and cover letter now lead with the reactor as the firm heat and power source of the hub; the national model follows as the setting for the hubs’ fuel.', 'En partie. Le résumé et la lettre commencent désormais par le réacteur comme source garantie du pôle.')),
        (T('Floating-point differences', 'Différences d’arrondi'), T('Noted; outputs reproduce byte for byte on our platform and to floating-point precision elsewhere.', 'Noté.')),
        (T('Repository, DOI, fees, declarations', 'Dépôt, DOI, frais, déclarations'), T('Author actions: replace the GitHub contents with Repository/, make a Zenodo release, obtain written confirmation of no charges for a 2027 acceptance, and confirm the prior-submission statement. The corresponding author has confirmed there are no patents or competing interests.', 'Actions des auteurs.'))]:
        add('h', h); add('p', t)
